const GINGEE_INFO={title:"Gingee Fort",subtitle:"The Troy of the East",location:"Villupuram District, Tamil Nadu, India",coordinates:"12.2514° N, 79.4172° E",elevation:"800 ft (240 m) above surrounding plains",builtEra:"Originally 12th Century CE (Expanded through 16th–18th Centuries)",primaryBuilders:"Ananta Konar (Konar Dynasty), Kurumbar & Nayak Rulers, Marathas, Mughals",architecturalStyle:"Dravidian Fortification & Indo-Islamic Citadel Engineering",nearestCity:"Tiruvannamalai (38 km) / Chennai (160 km)",status:"Protected Monument of National Importance (ASI) & Tentative UNESCO World Heritage Site (Maratha Military Architecture)",nicknameReason:"Coined 'Troy of the East' by the British and praised by Chhatrapati Shivaji Maharaj as 'the most impregnable fortress in India' due to its steep granite cliffs, triple-hill perimeter, and impenetrable defensive gorge."},GINGEE_SECTIONS=[{id:"overview",title:"Overview",icon:"🏰",summary:"Gingee Fort (Senji Fort) stands as one of the most formidable and impenetrable military strongholds in South Indian history.",description:"Spread over three massive granite hills—Rajagiri, Krishnagiri, and Chandrayandurg—connected by a 13-kilometer-long fortified wall, Gingee Fort encompasses a vast 11-square-kilometer complex. Renowned for its natural steep cliffs, drawbridge over a 60-foot deep chasm, 7-story Kalyana Mahal, and multi-layered granaries, it earned the title 'Troy of the East' from the British. Throughout history, it served as a contested regional seat for the Konar dynasty, Vijayanagara Nayaks, Bijapur Sultanate, Maratha Empire, Mughals, Carnatic Nawabs, French, and British forces."},{id:"history",title:"History",icon:"📜",summary:"Over eight centuries of royal rise, dramatic sieges, regional dominion, and heroic battles.",description:"Founded in the late 12th century by Ananta Konar of the local Konar dynasty, Gingee was transformed into a colossal stone citadel under the Vijayanagara Nayaks of Gingee (14th–16th centuries). In 1677, Maratha Emperor Chhatrapati Shivaji Maharaj captured the fort, fortifying its ramparts further. During the late 17th century, Gingee served as the capital of the Maratha Empire under Rajaram I, withstanding an extraordinary 8-year siege (1690–1698 CE) by Mughal Emperor Aurangzeb's general Zulfiqar Khan. In 1714 CE, the heroic 22-year-old Bundela prince Raja Desingu (Tej Singh) fought valiantly against the Nawab of Arcot, cementing Gingee's place in Tamil folklore."},{id:"builder",title:"Builder & Rulers",icon:"👑",summary:"Built by local chieftain Ananta Konar and expanded by centuries of legendary rulers and architects.",description:"Gingee Fort's architecture reflects layers of fortification built across different dynasties, each contributing unique defensive, water-harvesting, and palatial features."},{id:"architecture",title:"Architecture",icon:"🏛️",summary:"Impenetrable granite ramparts, gravity-fed water channels, multi-tiered granaries, and majestic towers.",description:"Gingee Fort showcases exceptional military engineering combined with Dravidian stone craft and Indo-Islamic palatial elements. Key highlights include Kalyana Mahal, huge granaries, secret escape tunnels, royal baths, and the Venkataramana Temple."},{id:"three-hills",title:"Three Hill Forts",icon:"⛰️",summary:"A triangular citadel complex spanning Rajagiri, Krishnagiri, and Chandrayandurg.",description:"The unique defense mechanism of Gingee relies on three distinct granite hill citadels, each functioning as a self-sufficient fort capable of holding out independently during a prolonged siege."},{id:"strategic",title:"Strategic Importance",icon:"🛡️",summary:"The gateway to northern Tamil Nadu, guarding inland trade routes and coastal approaches.",description:"Commanding the plains between the Eastern Ghats and the Coromandel Coast, Gingee Fort allowed its commanders to dominate northern Tamil Nadu. Its natural granite chasms and triple-hill design made forced entry nearly impossible without treason or prolonged blockade."},{id:"facts",title:"Interesting Facts",icon:"💡",summary:"Fascinating legends, engineering marvels, and historical records of Gingee Fort.",description:"Discover why the British called it the Troy of the East, how water was piped to the 7th floor, and the heroic saga of Raja Desingu."},{id:"gallery",title:"Image Gallery",icon:"🖼️",summary:"Visual showcase of Gingee Fort's towers, hilltops, temples, and fortifications.",description:"Explore high-resolution photography capturing the timeless grandeur of Gingee's granite peaks, Kalyana Mahal, and surrounding landscape."}],BUILDERS_LIST=[{name:"Ananta Konar",era:"c. 1190 – 1240 CE",dynasty:"Konar Dynasty",role:"Founder & Original Citadel Builder",contribution:"Constructed the initial mud-and-stone fort on Anandagiri hill (later renamed Rajagiri) after discovering a hidden treasure while herding cattle.",icon:"🏰"},{name:"Tubaki Krishnappa Nayak",era:"c. 1490 – 1520 CE",dynasty:"Nayak Dynasty of Gingee (Vijayanagara Vassals)",role:"Master Fortifier & Urban Planner",contribution:"Converted the hill fort into a massive granite fortress complex, built the outer 13-km perimeter wall, granaries, Kalyana Mahal foundation, and Venkataramana Temple.",icon:"🗡️"},{name:"Chhatrapati Shivaji Maharaj",era:"1677 CE",dynasty:"Maratha Empire",role:"Conqueror & Military Strategist",contribution:"Captured Gingee during his Southern Expedition (Dakshin Digvijay), overhauled its ramparts, created secondary moats, and declared it 'the most impregnable fort in India'.",icon:"🚩"},{name:"Rajaram I (Maratha King)",era:"1689 – 1698 CE",dynasty:"Maratha Empire",role:"Defender during 8-Year Siege",contribution:"Used Gingee as the operational capital of the Maratha Empire, holding off the full might of Mughal Emperor Aurangzeb's armies for 8 consecutive years.",icon:"🛡️"},{name:"Raja Desingu (Tej Singh Bundela)",era:"1714 CE",dynasty:"Bundela Rajput Chieftain",role:"Folk Hero & Legendary Ruler",contribution:"Refused to pay tribute to the Nawab of Arcot and fought heroically against overwhelming odds at age 22, creating a immortal legend commemorated in Tamil folk ballads.",icon:"⚔️"}],THREE_HILLS=[{id:"rajagiri",name:"Rajagiri (King's Hill / Anandagiri)",height:"800 ft (240 m)",difficulty:"Challenging (1,000+ granite steps)",highlights:["Kalyana Mahal","Chasm Drawbridge","Royal Granaries","Ranganatha Temple","Royal Citadel Peak"],description:"The tallest and most fortified peak of Gingee. Access to the upper citadel is cut off by a natural 60-foot deep, 24-foot wide chasm over which a narrow wooden drawbridge was placed. Invaders had to cross three tiers of heavy iron-spiked gates and steep narrow steps carved directly into sheer granite cliffs.",icon:"👑"},{id:"krishnagiri",name:"Krishnagiri (Queen's Hill)",height:"600 ft (180 m)",difficulty:"Moderate (Polished stone stairs)",highlights:["Audience Hall","Queen's Palace","Granary Towers","Polished Granite Step Trail","Audience Courtyard"],description:"Located north of Rajagiri, Krishnagiri features impressive stone masonry steps leading to royal reception halls, residential suites, granaries, and a hilltop temple. The masonry on Krishnagiri displays fine Vijaynagara stone finishing.",icon:"👸"},{id:"chandrayandurg",name:"Chandrayandurg (Chakkilidurg / Moon Hill)",height:"550 ft (170 m)",difficulty:"Strenuous (Rugged terrain)",highlights:["Military Outposts","Watchtowers","Southwest Bastions","Defensive Moat Outlook"],description:"Forming the southwestern corner of the triangular defense complex, Chandrayandurg served primarily as a military watch outpost. Its strategic position allowed defenders to spot approaching enemy artillery or cavalry miles away across the surrounding plains.",icon:"🌙"}],ARCH_FEATURES=[{title:"Kalyana Mahal (Wedding Palace)",type:"Royal Tower Architecture",description:"A 7-story square tower built in a blend of Dravidian and Indo-Islamic style. Features an open courtyard, central bath, and an ingenious clay pipe system that pumped water gravity-fed up to the top floor.",icon:"🕌"},{title:"Granaries & Provision Storehouses",type:"Logistical Engineering",description:"Massive stone structures with domed roofs designed to store grain for thousands of soldiers over years of blockade. Air vents and raised floors prevented humidity and pest infestation.",icon:"🌾"},{title:"Chasm Drawbridge & Natural Defenses",type:"Military Fortification",description:"A narrow drawbridge spanning a dizzying 60-foot deep natural ravine. Pulling up the drawbridge rendered the inner citadel completely inaccessible to attackers.",icon:"🌉"},{title:"Venkataramana Temple",type:"Vijayanagara Sacred Architecture",description:"Located in the lower fort, this grand temple complex features monolithic carved pillars, detailed puranic reliefs, and an outer corridor showcasing 16th-century craftsmanship.",icon:"🛕"},{title:"Interconnected Water Tanks & Cisterns",type:"Hydraulic Engineering",description:"Includes Chettikulam and Chakrakulam ponds, rainwater harvesting channels, and rock-cut cisterns that supplied fresh mountain spring water across all three hills year-round.",icon:"💧"},{title:"13-km Outer Rampart & Triple-Tier Gates",type:"Perimeter Defense",description:"Encircles 11 square kilometers with double granite walls, heavy iron-studded anti-elephant wooden gates, embrasures for cannons, and moat defenses.",icon:"🏰"}],TIMELINE_EVENTS=[{year:"c. 1190 CE",title:"Foundation by Ananta Konar",description:"Ananta Konar builds the first fortification on Anandagiri (Rajagiri) hill after discovering treasure."},{year:"1490–1520 CE",title:"Vijayanagara Expansion",description:"Tubaki Krishnappa Nayak expands Gingee into a major granite citadel with 3 hill forts and 13 km walls."},{year:"1649 CE",title:"Bijapur Sultanate Conquest",description:"General Mustapha Khan of the Bijapur Sultanate captures Gingee Fort from the last Nayak ruler."},{year:"1677 CE",title:"Chhatrapati Shivaji Maharaj Capture",description:"Maratha forces capture Gingee; Shivaji praises its defense and strengthens its bastions and moats."},{year:"1690–1698 CE",title:"The Great 8-Year Siege of Gingee",description:"Mughal forces led by Zulfiqar Khan besiege Maratha King Rajaram I; Gingee holds out for 8 full years."},{year:"1714 CE",title:"Raja Desingu's Heroic Last Stand",description:"22-year-old Raja Desingu fights the Arcot Nawab; his sacrifice becomes legendary Tamil folklore."},{year:"1750 CE",title:"French & British Occupation",description:"French forces under Bussy capture Gingee in a night surprise attack; later ceded to the British in 1761."},{year:"1921 CE",title:"National Monument Declaration",description:"Gingee Fort is designated a Protected National Monument under the Archaeological Survey of India (ASI)."}],INTERESTING_FACTS=[{id:1,title:"Why 'Troy of the East'?",category:"Epithet",fact:"British colonizers dubbed Gingee the 'Troy of the East' because, like legendary Troy, its formidable triple-hill topography, 60-ft gorge drawbridge, and massive outer walls made direct military storming almost impossible.",icon:"🏛️"},{id:2,title:"8-Year Siege Record",category:"Military",fact:"During the 1690–1698 siege, Mughal Emperor Aurangzeb spent immense gold and military resources attempting to take Gingee, keeping his main forces tied down in the South while Maratha forces reorganized in the Deccan.",icon:"🛡️"},{id:3,title:"Gravity Water Pipe to 7th Floor",category:"Engineering",fact:"The 7-story Kalyana Mahal featured terracotta water pipes built directly inside the masonry walls, carrying cool spring water up to the top floor using hydraulic gravity pressure without any pumps.",icon:"💧"},{id:4,title:"Ballad of Raja Desingu & Nila",category:"Folklore",fact:"The romantic and tragic heroic story of Raja Desingu and his loyal stallion Nila is celebrated across Tamil Nadu through the famous folk ballad 'Desingu Raja Kadhai' and popular street theater (Terukkuttu).",icon:"🐎"},{id:5,title:"Natural Air Conditioning",category:"Architecture",fact:"The inner rooms of the royal palaces were constructed with double walls and hollow terracotta ceiling blocks that trapped cool breeze and insulated against scorching Tamil Nadu summer heat.",icon:"🌬️"},{id:6,title:"Grain for 10,000 Troops",category:"Logistics",fact:"The granary towers at Gingee were designed to store over 2,000 metric tons of paddy and provisions—enough to feed a garrison of 10,000 soldiers for more than three years during a blockade.",icon:"🌾"}],GALLERY_IMAGES=[{url:"https://images.unsplash.com/photo-1590050752117-238cb0fb12b1?auto=format&fit=crop&w=1200&q=80",thumb:"https://images.unsplash.com/photo-1590050752117-238cb0fb12b1?auto=format&fit=crop&w=600&q=80",caption:"Rajagiri Hill Fort Citadel rising majestically above the green landscape of Gingee.",category:"Hill Forts",alt:"Rajagiri Hill Fort Citadel at Gingee"},{url:"https://images.unsplash.com/photo-1582510003544-4d00b7f74220?auto=format&fit=crop&w=1200&q=80",thumb:"https://images.unsplash.com/photo-1582510003544-4d00b7f74220?auto=format&fit=crop&w=600&q=80",caption:"The 7-story Kalyana Mahal (Wedding Palace) tower with Indo-Islamic archways.",category:"Architecture",alt:"Kalyana Mahal 7-Story Tower at Gingee Fort"},{url:"https://images.unsplash.com/photo-1600585154340-be6161a56a0c?auto=format&fit=crop&w=1200&q=80",thumb:"https://images.unsplash.com/photo-1600585154340-be6161a56a0c?auto=format&fit=crop&w=600&q=80",caption:"Imposing granite rampart walls and battlements encircling the Gingee citadel complex.",category:"Fortifications",alt:"Granite outer ramparts of Gingee Fort"},{url:"https://images.unsplash.com/photo-1564507592333-c60657eea523?auto=format&fit=crop&w=1200&q=80",thumb:"https://images.unsplash.com/photo-1564507592333-c60657eea523?auto=format&fit=crop&w=600&q=80",caption:"Venkataramana Temple carving and pillared halls within the lower Gingee fort campus.",category:"Temples",alt:"Venkataramana Temple pillared corridor at Gingee"},{url:"https://images.unsplash.com/photo-1548013146-72479768bada?auto=format&fit=crop&w=1200&q=80",thumb:"https://images.unsplash.com/photo-1548013146-72479768bada?auto=format&fit=crop&w=600&q=80",caption:"Panoramic view of Krishnagiri (Queen's Hill) fort towers against the morning sky.",category:"Hill Forts",alt:"Krishnagiri Queen Hill fort vista"},{url:"https://images.unsplash.com/photo-1596895111956-bf1cf0599ce5?auto=format&fit=crop&w=1200&q=80",thumb:"https://images.unsplash.com/photo-1596895111956-bf1cf0599ce5?auto=format&fit=crop&w=600&q=80",caption:"Historic stone granaries built to store grain for long sieges at Gingee.",category:"Architecture",alt:"Stone granaries at Gingee Fort"}];"undefined"!=typeof module&&module.exports&&(module.exports={GINGEE_INFO:GINGEE_INFO,GINGEE_SECTIONS:GINGEE_SECTIONS,BUILDERS_LIST:BUILDERS_LIST,THREE_HILLS:THREE_HILLS,ARCH_FEATURES:ARCH_FEATURES,TIMELINE_EVENTS:TIMELINE_EVENTS,INTERESTING_FACTS:INTERESTING_FACTS,GALLERY_IMAGES:GALLERY_IMAGES});